=Analiza el siguiente contexto: {{ $json.Contexto }}

Eres un experto en copywriting para Instagram. Genera ÚNICAMENTE un objeto JSON válido con esta estructura exacta:

{
  "titulo": "Título corto y potente (máx 50 caracteres)",
  "descripcion": "Texto principal del post (máximo 2.200 caracteres, con emojis si procede)",
  "hashtags": ["#hashtag1", "#hashtag2", "#hashtag3", "#hashtag4", "#hashtag5"]
}

REGLAS ESTRICTAS:
- Responde SOLO el JSON, sin texto antes ni después.
- No uses comillas triples ni bloques de código.
- No añadas explicaciones.
- El JSON debe ser 100% válido y parseable.

Contexto: {{ $json.Contexto }}

parameters.jsCode:
// Loop over input items and add a new field called 'myNewField' to the JSON of each one
for (const item of $input.all()) {
  item.json.Contexto = "Actúa como un experto en marketing para Instagram. Crea 1 descripción para publicitar flujos de n8n de aprendizaje o ejemplo con pequeñas operaciones en la web immersiveoffice.es";

  item.json.ContextoImg = "Flujo de workflow n8n";

  item.json.num_frases = 3;
}

return $input.all();

// Mismo problema que en el nodo anterior: el array puede venir truncado
// o envuelto en un objeto. Se aceptan las dos formas.
const raw = $input.first().json?.message?.content;
if (!raw) throw new Error('Ollama no devolvio texto');

let t = String(raw).trim()
  .replace(/^```(?:json)?\s*/i, '').replace(/```\s*$/, '')
  .replace(/[\u201C\u201D]/g, '"').replace(/[\u2018\u2019]/g, "'")
  .trim();

let frases = [];
try {
  const parsed = JSON.parse(t);
  frases = Array.isArray(parsed) ? parsed : (parsed.frases || Object.values(parsed).find(Array.isArray) || []);
} catch (e) {
  // rescatar las cadenas completas que haya, aunque el array este a medias
  frases = (t.match(/"([^"\\]*(?:\\.[^"\\]*)*)"/g) || []).map(s => JSON.parse(s));
}
frases = frases.filter(f => typeof f === 'string' && f.trim());
if (!frases.length) throw new Error(`No se pudieron extraer frases: ${t.slice(0, 200)}`);

return frases.map(valor => ({ json: { valor } }));

// llama3.2:1b a veces corta el JSON o lo envuelve en markdown.
// Se limpia, se intenta parsear y, si viene truncado, se cierran los
// corchetes/llaves que falten antes de rendirse.
const raw = $input.first().json?.message?.content;
if (!raw) throw new Error('Ollama no devolvio texto');

function parsearTolerante(texto) {
  let t = String(texto).trim().replace(/^```(?:json)?\s*/i, '').replace(/```\s*$/, '').trim();
  const ini = t.indexOf('{');
  if (ini > 0) t = t.slice(ini);
  try { return JSON.parse(t); } catch (e) {}

  // reparar truncado: cerrar cadenas y contenedores abiertos
  let reparado = t;
  const comillas = (reparado.match(/(?<!\\)"/g) || []).length;
  if (comillas % 2 === 1) reparado += '"';
  reparado = reparado.replace(/,\s*$/, '');
  const abiertas = [];
  let enCadena = false;
  for (let i = 0; i < reparado.length; i++) {
    const c = reparado[i];
    if (c === '"' && reparado[i - 1] !== '\\') enCadena = !enCadena;
    if (enCadena) continue;
    if (c === '{' || c === '[') abiertas.push(c);
    if (c === '}' || c === ']') abiertas.pop();
  }
  while (abiertas.length) reparado += abiertas.pop() === '{' ? '}' : ']';
  return JSON.parse(reparado);
}

let parsed;
try { parsed = parsearTolerante(raw); }
catch (e) { throw new Error(`JSON invalido generado por Ollama: ${String(raw).slice(0, 200)}`); }

return [{ json: {
  titulo: parsed.titulo || 'Sin titulo',
  descripcion: parsed.descripcion || '',
  hashtags: Array.isArray(parsed.hashtags) ? parsed.hashtags : [],
  raw_response: raw,
}}];

// Construye el grafo SDXL para ComfyUI con el contexto de imagen del flujo.
// El checkpoint flux1-schnell-fp8 del diseno original no esta instalado; los
// disponibles en este equipo son SDXL.
const ctx = $('Variable de Contexto').first().json;
const meta = $('Extraer Descripción y Título').first().json;
const frases = $input.all().map(i => i.json.valor).filter(Boolean);

const positivo = `${ctx.ContextoImg}, ${meta.titulo}, instagram post, clean composition, high detail`;
const negativo = 'blurry, low quality, watermark, text, deformed';

const grafo = {
  "4": { class_type: "CheckpointLoaderSimple", inputs: { ckpt_name: "sd_xl_base_1.0.safetensors" } },
  "5": { class_type: "EmptyLatentImage", inputs: { width: 1024, height: 1024, batch_size: 1 } },
  "6": { class_type: "CLIPTextEncode", inputs: { text: positivo, clip: ["4", 1] } },
  "7": { class_type: "CLIPTextEncode", inputs: { text: negativo, clip: ["4", 1] } },
  "3": { class_type: "KSampler", inputs: {
           seed: Math.floor(Math.random() * 1e12), steps: 25, cfg: 7,
           sampler_name: "euler", scheduler: "normal", denoise: 1,
           model: ["4", 0], positive: ["6", 0], negative: ["7", 0], latent_image: ["5", 0] } },
  "8": { class_type: "VAEDecode", inputs: { samples: ["3", 0], vae: ["4", 2] } },
  "9": { class_type: "SaveImage", inputs: { filename_prefix: "n8n_instagram", images: ["8", 0] } },
};
return [{ json: {
  titulo: meta.titulo, descripcion: meta.descripcion, hashtags: meta.hashtags, frases,
  prompt_imagen: positivo, payload: { prompt: grafo, client_id: 'n8n' },
}}];

// Sondea ComfyUI hasta que el trabajo termina. Una espera fija no sirve:
// el tiempo de render depende del modelo, la resolucion y la carga de la GPU.
const promptId = $('Enviar a ComfyUI').first().json.prompt_id;
const base = 'http://host.docker.internal:8188';
const maxIntentos = 150;      // 150 x 4 s = 10 min de margen
const esperaMs = 4000;

let salida = null;
for (let intento = 0; intento < maxIntentos; intento++) {
  const historial = await this.helpers.httpRequest({
    method: 'GET', url: `${base}/history/${promptId}`, json: true,
  });
  const entrada = historial && historial[promptId];
  if (entrada && entrada.outputs && Object.keys(entrada.outputs).length) {
    salida = entrada;
    break;
  }
  const estado = entrada && entrada.status;
  if (estado && estado.status_str === 'error') {
    throw new Error(`ComfyUI fallo el trabajo ${promptId}: ${JSON.stringify(estado.messages || [])}`);
  }
  await new Promise(r => setTimeout(r, esperaMs));
}
if (!salida) {
  throw new Error(`ComfyUI no termino el trabajo ${promptId} en ${(maxIntentos * esperaMs) / 1000} s.`);
}

const imagenes = Object.values(salida.outputs).flatMap(o => o.images || []);
if (!imagenes.length) throw new Error('ComfyUI no devolvio ninguna imagen.');

const img = imagenes[0];
return [{ json: {
  ...$('Construir Prompt ComfyUI').first().json,
  filename: img.filename, subfolder: img.subfolder || '', type: img.type || 'output',
}}];
